public class Engine {
    protected int horsepower;

    public Engine(int horsepower) {
        this.horsepower = horsepower;
    }

    public void start() {
        System.out.println("Engine starting with " + horsepower + " HP.");
    }
}

public class ElectricCar extends Engine {
    private int batteryCapacity;

    public ElectricCar(int horsepower, int batteryCapacity) {
        super(horsepower); // Explicitly invokes superclass constructor
        this.batteryCapacity = batteryCapacity;
    }

    @Override
    public void start() {
        super.start(); // Extends behavior of the parent method
        System.out.println("Electric drive engaged. Battery: " + batteryCapacity + "kWh.");
    }
}
